import { DialogPrimitive } from '@chameleon-ui/primitives'
import type { PointerEvent as ReactPointerEvent, ReactNode } from 'react'
import { useRef, useState } from 'react'
import './styles.css'

export interface ActionSheetAction {
  value: string
  label: ReactNode
}

export interface ActionSheetProps {
  triggerLabel: string
  title: string
  cancelLabel: string
  actions: ActionSheetAction[]
  open?: boolean
  onOpenChange?: (open: boolean) => void
  onAction?: (value: string) => void
  className?: string
}

/** Drag distance (px) past which releasing the handle dismisses the sheet. */
const DISMISS_THRESHOLD_PX = 72

export function ActionSheet({
  triggerLabel,
  title,
  cancelLabel,
  actions,
  open,
  onOpenChange,
  onAction,
  className,
}: ActionSheetProps) {
  const [internalOpen, setInternalOpen] = useState(false)
  const isOpen = open ?? internalOpen
  const drag = useRef<{ pointerId: number; startY: number; delta: number } | null>(null)
  const contentRef = useRef<HTMLDivElement | null>(null)

  function requestOpenChange(next: boolean) {
    if (open === undefined) setInternalOpen(next)
    onOpenChange?.(next)
  }

  function applyDragOffset(delta: number) {
    const content = contentRef.current
    if (!content) return
    content.style.transform = delta > 0 ? `translateY(${delta}px)` : ''
  }

  function onHandlePointerDown(event: ReactPointerEvent<HTMLSpanElement>) {
    drag.current = { pointerId: event.pointerId, startY: event.clientY, delta: 0 }
    try {
      event.currentTarget.setPointerCapture?.(event.pointerId)
    } catch {
      // jsdom has no pointer capture; dragging still works via element handlers.
    }
  }

  function onHandlePointerMove(event: ReactPointerEvent<HTMLSpanElement>) {
    if (drag.current?.pointerId !== event.pointerId) return
    drag.current.delta = Math.max(0, event.clientY - drag.current.startY)
    applyDragOffset(drag.current.delta)
  }

  function onHandlePointerEnd(event: ReactPointerEvent<HTMLSpanElement>) {
    if (drag.current?.pointerId !== event.pointerId) return
    const { delta } = drag.current
    drag.current = null
    applyDragOffset(0)
    if (delta > DISMISS_THRESHOLD_PX) requestOpenChange(false)
  }

  const classes = ['cu-action-sheet', 'cu-action-sheet__content', className].filter(Boolean).join(' ')

  return (
    <DialogPrimitive.Root open={isOpen} onOpenChange={(details) => requestOpenChange(details.open)}>
      <DialogPrimitive.Trigger className="cu-action-sheet__trigger">{triggerLabel}</DialogPrimitive.Trigger>
      <DialogPrimitive.Portal>
        <DialogPrimitive.Backdrop className="cu-action-sheet__backdrop" />
        <DialogPrimitive.Positioner className="cu-action-sheet__positioner">
          <DialogPrimitive.Content
            ref={contentRef}
            className={classes}
            data-ai-role="action-sheet"
            data-ai-intent="choose-action"
            data-ai-state={isOpen ? 'open' : 'closed'}
          >
            <span
              className="cu-action-sheet__handle"
              aria-hidden="true"
              onPointerDown={onHandlePointerDown}
              onPointerMove={onHandlePointerMove}
              onPointerUp={onHandlePointerEnd}
              onPointerCancel={onHandlePointerEnd}
            />
            <DialogPrimitive.Title className="cu-action-sheet__title">{title}</DialogPrimitive.Title>
            <div className="cu-action-sheet__actions">
              {actions.map((action) => (
                <button
                  key={action.value}
                  type="button"
                  className="cu-action-sheet__action"
                  onClick={() => {
                    onAction?.(action.value)
                    requestOpenChange(false)
                  }}
                >
                  {action.label}
                </button>
              ))}
            </div>
            <DialogPrimitive.CloseTrigger className="cu-action-sheet__cancel">
              {cancelLabel}
            </DialogPrimitive.CloseTrigger>
          </DialogPrimitive.Content>
        </DialogPrimitive.Positioner>
      </DialogPrimitive.Portal>
    </DialogPrimitive.Root>
  )
}

{
  "schemaVersion": "0.2",
  "slug": "action-sheet",
  "name": "ActionSheet",
  "status": "experimental",
  "purpose": "Presents a set of contextual actions in a bottom-anchored panel; the compact-screen morph target of Dialog.",
  "scenarios": [
    "Offer share, edit, and delete actions for a list item",
    "Confirm a destructive choice with a visible cancel escape",
    "Collect one choice on a phone without leaving the current page"
  ],
  "props": {
    "triggerLabel": {
      "type": "string",
      "required": true,
      "description": "Trigger button label."
    },
    "title": {
      "type": "string",
      "required": true,
      "description": "Action sheet title."
    },
    "cancelLabel": {
      "type": "string",
      "required": true,
      "description": "Cancel button label."
    },
    "actions": {
      "type": "string",
      "required": true,
      "description": "Array of actions with value and label."
    },
    "open": {
      "type": "boolean",
      "required": false,
      "description": "Controlled open state."
    },
    "onOpenChange": {
      "type": "event",
      "required": false,
      "description": "Called when open state changes (trigger, Escape, backdrop, cancel, or drag dismiss)."
    },
    "onAction": {
      "type": "event",
      "required": false,
      "description": "Called with the action value when an action is chosen; the sheet then closes."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "open",
      "description": "Sheet is visible; focus is trapped inside."
    },
    {
      "name": "closed",
      "description": "Sheet is hidden; only the trigger is in the tab order."
    }
  ],
  "composition": {
    "allowedParents": [
      "app-shell",
      "page"
    ],
    "allowedChildren": [
      "button"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not open multiple action sheets.",
    "Do not use for long forms; use Dialog or a page instead.",
    "Do not remove the cancel control; it is the always-visible escape."
  ],
  "a11y": {
    "role": "dialog",
    "keyboard": [
      "Tab cycles inside",
      "Escape closes",
      "Enter/Space activates an action"
    ],
    "focus": "Focus moves inside on open and returns to the trigger on close; delegated to Ark UI / Zag focus trap.",
    "labeling": "Title labels the sheet; every action is a real button with its visible label.",
    "wcag": [
      "2.1.1",
      "2.4.3",
      "2.5.5"
    ]
  },
  "responsive": {
    "strategy": "Bottom-anchored full-width panel with drag handle on compact; bounded centered panel without the handle on tablet and desktop. The morph is container-driven via the viewport-sized positioner.",
    "breakpoints": {
      "compact": "Full-width bottom panel; drag handle visible, swipe down or Escape closes; action and cancel hit areas >= 44px.",
      "medium": "Centered panel with max inline size 30rem; drag handle hidden; Escape and cancel close.",
      "large": "Same as medium."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only; the panel is block-end anchored and direction-neutral, actions stack in document order.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "action-sheet",
    "states": [
      "open",
      "closed"
    ],
    "intents": [
      "choose-action"
    ]
  }
}

{
  "actionSheet": {
    "label": "アクションシート",
    "cancel": "キャンセル"
  }
}

.cu-action-sheet__backdrop {
  position: fixed;
  inset: 0;
  z-index: 30;
  background: color-mix(in srgb, var(--cu-color-background-inverse) 66%, transparent);
  backdrop-filter: blur(var(--cu-blur-surface, 0px));
  -webkit-backdrop-filter: blur(var(--cu-blur-surface, 0px));
}

/*
 * Phase 5 container-query whitelist member: the positioner is viewport-sized
 * (fixed inset 0) and acts as the query container; the content morphs from
 * full-width bottom panel to a bounded centered panel by container size.
 */
.cu-action-sheet__positioner {
  position: fixed;
  inset: 0;
  z-index: 31;
  display: grid;
  place-items: end center;
  overflow: auto;
  container-name: action-sheet;
  container-type: inline-size;
}

.cu-action-sheet__content {
  inline-size: 100%;
  max-block-size: 75vh;
  overflow: auto;
  padding-block-start: var(--cu-space-1);
  padding-block-end: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
  border-start-start-radius: var(--cu-radius-xl, var(--cu-radius-lg));
  border-start-end-radius: var(--cu-radius-xl, var(--cu-radius-lg));
  border-end-start-radius: 0;
  border-end-end-radius: 0;
  color: var(--cu-color-fg-default);
  background: var(
    --cu-color-background-translucent-thick,
    var(--cu-color-background-elevated, var(--cu-color-background-default))
  );
  -webkit-backdrop-filter: saturate(var(--cu-saturate-frost, 1))
    blur(var(--cu-blur-thick, var(--cu-blur-surface, 0px)));
  backdrop-filter: saturate(var(--cu-saturate-frost, 1)) blur(var(--cu-blur-thick, var(--cu-blur-surface, 0px)));
  box-shadow: var(--cu-shadow-lg);
  transition: transform 140ms ease;
}

/* Drag-to-dismiss handle: hit area meets the 44px touch target floor. */
.cu-action-sheet__handle {
  display: block;
  min-block-size: var(--cu-touch-target-min);
  cursor: grab;
  touch-action: none;
}

.cu-action-sheet__handle::before {
  content: '';
  display: block;
  margin-block: var(--cu-space-2);
  margin-inline: auto;
  inline-size: 2.25rem;
  block-size: 0.25rem;
  border-radius: var(--cu-radius-sm);
  background: var(--cu-color-border-default);
}

.cu-action-sheet__title {
  margin-block: 0 var(--cu-space-2);
  font-size: 1rem;
  font-weight: 700;
  text-align: center;
}

.cu-action-sheet__actions {
  display: flex;
  flex-direction: column;
}

.cu-action-sheet__action,
.cu-action-sheet__cancel {
  display: flex;
  align-items: center;
  justify-content: center;
  min-block-size: var(--cu-touch-target-min);
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border: none;
  border-block-start: 1px solid var(--cu-color-border-default);
  background: transparent;
  color: var(--cu-color-fg-default);
  font: inherit;
  cursor: pointer;
}

.cu-action-sheet__cancel {
  margin-block-start: var(--cu-space-2);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  font-weight: 650;
}

@media (hover: hover) {
  .cu-action-sheet__action:hover,
  .cu-action-sheet__cancel:hover {
    background: color-mix(in srgb, var(--cu-color-background-default) 92%, var(--cu-color-palette-brand));
  }
}

.cu-action-sheet__action:focus-visible,
.cu-action-sheet__cancel:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 3px;
}

/* 48rem == breakpoint.tablet, see packages/tokens/src/core/breakpoint.json. */
@container (min-width: 48rem) {
  .cu-action-sheet__content {
    align-self: center;
    inline-size: min(100%, 30rem);
    margin-block: var(--cu-space-3);
    border-radius: var(--cu-radius-xl, var(--cu-radius-lg));
  }

  .cu-action-sheet__handle {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cu-action-sheet__backdrop,
  .cu-action-sheet__content {
    transition-duration: 0.01ms;
  }
}
